from pysat.solvers import Solver
from pysat.card import CardEnc

# 12 pigeons, 11 holes (0..10)
pigeons = range(12)
holes = range(11)

# variable mapping: x[i][j] = pigeon i in hole j
# use 1-based indexing for SAT variables
var = {}
cnt = 1
for i in pigeons:
    for j in holes:
        var[(i,j)] = cnt
        cnt += 1

solver = Solver(name='g3')

# each pigeon in exactly one hole
for i in pigeons:
    lits = [var[(i,j)] for j in holes]
    # at least one
    solver.add_clause(lits)
    # at most one: pairwise or cardinality
    # use pairwise for small numbers
    for a in range(len(lits)):
        for b in range(a+1, len(lits)):
            solver.add_clause([-lits[a], -lits[b]])

# each hole at most one pigeon
for j in holes:
    lits = [var[(i,j)] for i in pigeons]
    for a in range(len(lits)):
        for b in range(a+1, len(lits)):
            solver.add_clause([-lits[a], -lits[b]])

sat = solver.solve()
print("SAT:", sat)
if sat:
    model = solver.get_model()
    assignment = {}
    for i in pigeons:
        for j in holes:
            v = var[(i,j)]
            if v in model:
                assignment[i] = j
    print(assignment)
else:
    print("UNSAT")
